"place/bauernhofspielgruppe-zwargehof-ried-bei-kerzers/hours":{"en":"1f3d113290454dd58d56d5d04210e90ecbfcd75a66a09554c5e6655e4c4bb3e0","text":"Dienstag und Mittwoch 08:30–11:00"},
"place/bauernhofspielgruppe-zwargehof-ried-bei-kerzers/closures":{"en":"64ec7d8d00d38bb3679a8de9e6ed272e767675537adc70cce94240a19327bd67","text":"Richtet sich nach dem Kalender der Primarschule Kerzers für Schulferien, Feiertage und schulfreie Tage"},
