"place/creche-le-bac-a-sages-grandsivaz/pedagogy":{"en":"660e0c6d511a471fa52bca938fc26a33484d49727ba759bdf2b994c008961312","text":"Tägliche Aktivitäten im Freien bei jedem Wetter; Spielen mit alltäglichen, geschlechtsneutralen Gegenständen; Zusammenarbeit und Beteiligung an Alltagsaufgaben"},
