"place/creche-le-bosquet-givisiez/ageTo":{"en":"5b28999735196c149fe020d82352bef7323f5b5ae0303a33df8a7f35d0ee0c5c","text":"Bis zum Schuleintritt; für Kinder, die vor dem 31. Juli 4 Jahre alt geworden sind, endet der Vertrag an diesem Datum"},
