"place/maternelle-les-castors-cugy/meals":{"en":"7c72c5d5354989412b485fad18554e0972024b11f736f06776e540cc3e7e6a3d","text":"Jedes Kind bringt eine kleine Zwischenmahlzeit von zu Hause mit."},
